// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public {
        // owner is determined at construction as msg.sender; use a placeholder EOA
        // so later owner-only calls come from a plain address that accepts transfers.
        vm.prank(address(0xBEEF));
        c = new SimpleWallet();
    }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(actor.code.length == 0); // plain EOA: transfer always succeeds
        vm.prank(actor);
        c = new SimpleWallet(); // actor is the owner

        uint256 bal = bound(amount, 1, type(uint256).max);
        vm.deal(address(c), bal);

        vm.prank(actor);
        c.withdraw(bal);

        assertTrue(address(c).balance == 0, "withdraw(v) must move v wei out");
    }
}
